# 4. Kiểm tra hoặc tạo Sheet 'English'
if "English" in wb.sheetnames:
    ws = wb["English"]
    ws.delete_rows(1, ws.max_row)  # Xóa nội dung cũ để cập nhật mới
else:
    ws = wb.create_sheet("English")

# 5. Ghi Tiêu đề Cột (Header)
headers = ["Word", "IPA", "Vietnamese", "PartOfSpeech", "Example", "Example Meaning"]
ws.append(headers)

# 6. Ghi 200 dòng dữ liệu
for item in toeic_vocab_200:
    ws.append(list(item))

# 7. Lưu lại File
wb.save(file_path)
